 "content": "from collections import Counter


def _runs(values, color):
    found = []
    start = None
    for i in range(len(values) + 1):
        value = values[i] if i < len(values) else None
        if value == color and start is None:
            start = i
        elif value != color and start is not None:
            found.append((start, i - 1))
            start = None
    return found


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    colors = set(counts) - {background}

    # Locate equal-length colored runs on opposite borders: these are the rails.
    rails = []
    for color in colors:
        top = _runs(grid[0], color)
        bottom = _runs(grid[-1], color)
        for a in top:
            for b in bottom:
                if a[1] - a[0] == b[1] - b[0]:
                    rails.append(("horizontal", color, a, b))
        left = _runs([grid[r][0] for r in range(h)], color)
        right = _runs([grid[r][-1] for r in range(h)], color)
        for a in left:
            for b in right:
                if a[1] - a[0] == b[1] - b[0]:
                    rails.append(("vertical", color, a, b))
    if not rails:
        return out
    axis, rail_color, first, second = max(
        rails, key=lambda item: item[2][1] - item[2][0]
    )
    marker_colors = colors - {rail_color}
    if not marker_colors:
        return out
    marker_color = max(marker_colors, key=lambda c: counts[c])

    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == marker_color]
    marker_set = set(markers)
    paired_marker_offsets = set()

    if axis == "horizontal":
        for r, c in markers:
            if first[0] <= c <= first[1]:
                source, target, edge_r, inward = first, second, 0, 1
            elif second[0] <= c <= second[1]:
                source, target, edge_r, inward = second, first, h - 1, -1
            else:
                continue
            offset = c - source[0]
            paired_c = target[0] + offset
            # Stroke from the source edge to the marker; preserve a 4 at its tip.
            rr = edge_r + inward
            while 0 <= rr < h and ((inward > 0 and rr <= r) or (inward < 0 and rr >= r)):
                out[rr][c] = marker_color
                rr += inward
            # The paired coordinate is projected through the complete interior.
            for rr in range(1, h - 1):
                out[rr][paired_c] = marker_color
            out[r][c] = 4
            if (r, paired_c) in marker_set:
                paired_marker_offsets.add((r, paired_c))
    else:
        for r, c in markers:
            if first[0] <= r <= first[1]:
                source, target, edge_c, inward = first, second, 0, 1
            elif second[0] <= r <= second[1]:
                source, target, edge_c, inward = second, first, w - 1, -1
            else:
                continue
            offset = r - source[0]
            paired_r = target[0] + offset
            cc = edge_c + inward
            while 0 <= cc < w and ((inward > 0 and cc <= c) or (inward < 0 and cc >= c)):
                out[r][cc] = marker_color
                cc += inward
            for cc in range(1, w - 1):
                out[paired_r][cc] = marker_color
            out[r][c] = 4
            if (paired_r, c) in marker_set:
                paired_marker_offsets.add((paired_r, c))

    # If two markers occupy exactly corresponding offsets on opposite rails,
    # the projected stroke through the later (row-major) point remains visible.
    if paired_marker_offsets:
        for pos in paired_marker_offsets:
            out[pos[0]][pos[1]] = marker_color
    return out


